			/*updateBuyerMpSoPrApprDtList*/
            UPDATE ICOMPRDT A                                                                                               
              SET  A.STATUS = 'R'
               , A.REF_ADD_USER_ID = #{APPR_0}
               , A.PURCHASER_ID = #{APPR_1}
               , A.RECV_QTY = A.TARGET_QTY
               , A.RECV_FLAG = 'PS'
               , A.SAVE_FLAG = 'PX'
               , A.REF_NO = #{PX_NO}
               , A.REF_SEQ = A.PR_SEQ
               WHERE A.BUYER = #{BUYER}                                                                         
                 AND A.PR_NO = #{PR_NO}   
                 AND A.RECV_FLAG NOT IN ('GR','PR')



			/*updateBuyerMpSoPrApprHdList*/
            UPDATE ICOMPRHD A                                                                                               
             SET A.RECV_FLAG = 'PS'
               , A.SAVE_FLAG = 'PX'
               WHERE A.BUYER = #{BUYER}                                                                         
                 AND A.PR_NO = #{PR_NO}
